export function prepareEmailSummaryWindow({ searchScope, recipient, cc }, anchor) {
  const cleanAddress = (value) => {
    if (typeof value !== 'string' || !/^[^\s@<>,;]+@[^\s@<>,;]+\.[^\s@<>,;]+$/u.test(value.trim())) throw new Error('Configure a plain recipient email address.');
    return value.trim();
  };
  if (typeof searchScope !== 'string' || !searchScope.trim() || searchScope.includes('YOUR_GMAIL_SEARCH_SCOPE')) throw new Error('Configure the Gmail search scope.');
  const to = cleanAddress(recipient);
  if (!Array.isArray(cc)) throw new Error('CC must be an array of plain email addresses.');
  const copies = cc.map(cleanAddress), end = new Date(anchor).getTime();
  if (!Number.isSafeInteger(end) || end < Date.UTC(2000, 0, 2)) throw new Error('Invalid captured execution time.');
  const offset = 330 * 60 * 1000, local = new Date(end + offset);
  const today = Date.UTC(local.getUTCFullYear(), local.getUTCMonth(), local.getUTCDate());
  const start = today - 86400000 - offset, endSeconds = Math.floor(end / 1000);
  const startDate = new Date(start + offset).toISOString().slice(0, 10);
  const endLabel = local.toISOString().slice(0, 16).replace('T', ' ');
  return { query: '(' + searchScope.trim() + ') after:' + Math.floor(start / 1000) + ' before:' + endSeconds,
    recipient: to, cc: copies, windowStart: new Date(start).toISOString(), windowEnd: new Date(endSeconds * 1000).toISOString(),
    subject: 'Email summary | ' + startDate + ' 00:00 to ' + endLabel + ' Asia/Kolkata' };
}

export default function prepareWindow(input) {
  return prepareEmailSummaryWindow(input, new Date().toISOString());
}

