export default function collectEmailPage({ previousState, messages, nextPageToken }) {
  if (previousState === null) {
    if (messages !== null) throw new Error('Unexpected Gmail page before the collection starts.');
    return { state: { messageIds: [], seenCursors: [] }, pageToken: null, more: true, count: 0 };
  }
  if (!previousState || !Array.isArray(previousState.messageIds) || !Array.isArray(previousState.seenCursors) || !Array.isArray(messages)) throw new Error('Invalid Gmail page collection state.');
  const added = messages.map(message => {
    if (!message || typeof message.messageId !== 'string' || !message.messageId.trim()) throw new Error('Gmail returned a message without an ID.');
    return message.messageId;
  });
  if (nextPageToken !== null && (typeof nextPageToken !== 'string' || !nextPageToken)) throw new Error('Gmail returned an invalid pagination cursor.');
  if (nextPageToken !== null && previousState.seenCursors.includes(nextPageToken)) throw new Error('Gmail repeated a pagination cursor.');
  const state = { messageIds: [...previousState.messageIds, ...added], seenCursors: nextPageToken === null ? [...previousState.seenCursors] : [...previousState.seenCursors, nextPageToken] };
  return { state, pageToken: nextPageToken, more: nextPageToken !== null, count: state.messageIds.length };
}

