export function emailSummaryFields(message, id, alreadyDecoded = false) {
  if (typeof id !== 'string' || !id || !message || message.messageId !== id || (message.snippet != null && typeof message.snippet !== 'string')) throw new Error('Gmail returned a different message or invalid snippet.');
  const headers = message.payload?.headers ?? [];
  if (!Array.isArray(headers)) throw new Error('Gmail did not return message headers.');
  const header = (name) => {
    const values = headers.filter((entry) => typeof entry?.name === 'string' && entry.name.toLowerCase() === name);
    if (values.some((entry) => typeof entry.value !== 'string')) throw new Error('Gmail returned an invalid header.');
    return values.map((entry) => entry.value).join(', ');
  };
  const rawSnippet = message.snippet ?? '';
  const snippet = alreadyDecoded ? rawSnippet : rawSnippet.replace(/&amp;|&lt;|&gt;|&#39;|&quot;/gu, (entity) => ({ '&amp;': '&', '&lt;': '<', '&gt;': '>', '&#39;': "'", '&quot;': '"' })[entity]);
  return { id, From: header('from'), To: header('to'), CC: header('cc'), snippet };
}

export default function collectEmailMessage({ previousState, lastMessageId, lastSnippet, lastPayload, messageIds }) {
  if (!Array.isArray(messageIds) || messageIds.length === 0 || messageIds.some(id => typeof id !== 'string' || !id.trim())) throw new Error('Expected a nonempty Gmail message ID collection.');
  let state;
  if (previousState === null) {
    if (lastMessageId !== null) throw new Error('Unexpected Gmail message before collection starts.');
    state = { index: 0, emails: [] };
  } else {
    if (!previousState || !Number.isSafeInteger(previousState.index) || previousState.index < 0 || previousState.index >= messageIds.length || !Array.isArray(previousState.emails) || previousState.emails.length !== previousState.index) throw new Error('Invalid Gmail metadata collection state.');
    state = { index: previousState.index + 1, emails: [...previousState.emails, emailSummaryFields({ messageId: lastMessageId, snippet: lastSnippet, payload: lastPayload }, messageIds[previousState.index])] };
  }
  return { state, messageId: state.index < messageIds.length ? messageIds[state.index] : '', more: state.index < messageIds.length, count: state.index };
}

