export default function prepareCollectedEmailData({ state, total }) {
  if (!state || !Array.isArray(state.emails) || !Number.isSafeInteger(total) || total <= 0 || state.index !== total || state.emails.length !== total) throw new Error('The complete Gmail metadata collection is required before summarizing.');
  return { emailData: JSON.stringify(state.emails), count: total };
}

