export function formatEmailSummary(summary) {
  const nonblank = (value) => typeof value === 'string' && value.trim().length > 0;
  if (!summary || !Array.isArray(summary.summary_of_emails) || !Array.isArray(summary.actions)
    || summary.summary_of_emails.some((value) => !nonblank(value))
    || summary.actions.some((value) => !value || !nonblank(value.name) || !nonblank(value.action))) throw new Error('The model did not return a complete email summary.');
  const escape = (value) => value.replace(/[&<>"']/gu, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
  const points = summary.summary_of_emails.map((value) => '<li>' + escape(value) + '</li>').join('');
  const actions = summary.actions.map((value) => '<li><strong>' + escape(value.name) + ':</strong> ' + escape(value.action) + '</li>').join('');
  return '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>Email summary</title></head><body><h1>Email summary</h1><h2>Summary of emails</h2><ul>' + points + '</ul><h2>Actions</h2><ul>' + actions + '</ul></body></html>';
}

export default function prepareEmail({ summary }) {
  return { html: formatEmailSummary(summary) };
}

