export default function confirmEmail({ messageId, count, windowStart, windowEnd }) {
  if (typeof messageId !== 'string' || !messageId.trim()) throw new Error('Gmail did not confirm a sent message ID.');
  return { status: 'sent', messageId, count, windowStart, windowEnd };
}
